import { createHash, randomBytes } from 'node:crypto'

// Credencial de un solo uso del batch E1 del protocolo ENOS. Vive aislada en
// un módulo sin dependencias más allá de node:crypto: la consumen tanto rutas
// de Next como scripts de emisión, y no debe arrastrar el ORM ni el resto del
// grafo de imports.
//
// El principio es simple: SOLO el hash se persiste, nunca el token en claro.
// Quien emite ve el token una única vez (para mandarlo por el canal que
// corresponda) y la base guarda únicamente `tokenHash`. Si la base se filtra,
// el atacante obtiene hashes, no credenciales usables.

const BYTES_TOKEN = 16 // 128 bits de entropía: suficiente para una credencial de un solo uso.
const DIAS_VALIDEZ_POR_DEFECTO = 30
const MS_POR_DIA = 24 * 60 * 60 * 1000

// El token se codifica en base64url (alfabeto A-Z a-z 0-9 - _): sin '+', '/' ni
// relleno '=', así que viaja entero dentro de una URL sin escapar y sin romper
// los buscadores de query string.
export function generarToken(): { token: string; tokenHash: string } {
  const token = randomBytes(BYTES_TOKEN).toString('base64url')
  return { token, tokenHash: hashearToken(token) }
}

// Misma función de hash que usa generarToken internamente, expuesta para
// verificar un token recibido contra el `tokenHash` guardado en la base. La
// verificación real es un lookup por igualdad de hash en la DB: no se usa
// timingSafeEqual acá a propósito. Comparar un hash SHA-256 de un valor de
// alta entropía contra otro valor guardado no filtra información útil por
// timing — no hay un secreto de baja entropía que un atacante pueda ir
// adivinando byte a byte, y el hash ya está pensado para ser público en
// tránsito de verificación.
export function hashearToken(token: string): string {
  return createHash('sha256').update(token).digest('hex')
}

// true si `ahora` ya alcanzó o pasó la expiración. El borde es inclusivo:
// justo en el instante de vencimiento la credencial ya no sirve.
export function tokenExpirado(tokenExpiraEn: string, ahora: Date = new Date()): boolean {
  return ahora.getTime() >= new Date(tokenExpiraEn).getTime()
}

// Vencimiento de la CREDENCIAL, independiente del vencimiento de SLA de la
// verificación (que vive en su propio módulo). Son relojes distintos: este
// dice hasta cuándo sirve el enlace para canjearse; el de SLA dice cuánto
// puede tardar la verificación una vez iniciada. No unificar acá.
export function calcularVencimientoToken(
  ahora: Date = new Date(),
  diasValidez: number = DIAS_VALIDEZ_POR_DEFECTO,
): string {
  return new Date(ahora.getTime() + diasValidez * MS_POR_DIA).toISOString()
}

import { createHmac, timingSafeEqual } from 'node:crypto'

// Sesión acotada por CUE, canjeada de la credencial de verificación (batch E1
// del protocolo ENOS). Un director que entra por el enlace de "Hay afectación"
// puede usar el formulario de parte SIN la contraseña compartida, pero SÓLO
// para el CUE exacto de la verificación de la que canjeó, y sólo mientras esta
// sesión no venció.
//
// Por qué una cookie distinta y no reusar la de acceso público: la de acceso
// público prueba "alguien conoce la contraseña compartida" y sirve para todo
// el recorrido; ésta prueba "el servidor emitió esta sesión para ESTE CUE tras
// canjear un token válido". Propósito, payload y cookie distintos. Comparten la
// env var como secreto HMAC porque es un secreto de servidor ya configurado,
// no una credencial de usuario; firmar dos payloads distintos con la misma
// clave no mezcla las sesiones (una firma no es válida para el otro formato).
//
// Alcance: nunca lista ni abre partes de otro CUE, nunca otorga rol admin, ni
// se amplía a ningún otro alcance. La comparación de CUE es parte de la
// validación, no un filtro posterior.

export const NOMBRE_COOKIE_SESION_VERIFICACION = 'verificacion_sesion'
const DURACION_SESION_MS = 1000 * 60 * 30 // 30 minutos

// Duplicada a propósito desde acceso-publico.ts, que la mantiene privada: ese
// archivo se declara la única costura con el mundo público y no exporta sus
// helpers. Importarla acá acoplaría este módulo a su implementación interna;
// mismo criterio que ya usa acceso-parte.ts para no acoplarse.
function obtenerSecreto(): string {
  const secreto = process.env.PROBLEMATICAS_ACCESO_PASSWORD
  if (!secreto) {
    throw new Error('PROBLEMATICAS_ACCESO_PASSWORD no está configurada')
  }
  return secreto
}

function firmar(payload: string, secreto: string): string {
  return createHmac('sha256', secreto).update(payload).digest('base64url')
}

// Comparación en tiempo constante. Nunca uses === contra la firma: filtraría
// por timing dónde difieren.
function iguales(a: string, b: string): boolean {
  const bufA = Buffer.from(a)
  const bufB = Buffer.from(b)
  if (bufA.length !== bufB.length) {
    // Igual comparamos algo del mismo largo que a, para no salir antes y no
    // filtrar por timing que las longitudes no coinciden.
    timingSafeEqual(bufA, bufA)
    return false
  }
  return timingSafeEqual(bufA, bufB)
}

// Token de sesión acotada: "verificacionId|cueAnexo|expiración.firma". Se usa
// `|` como separador porque ni verificacionId (uuid) ni cueAnexo (dígitos) lo
// contienen. La firma prueba que el servidor emitió esta sesión; el CUE dentro
// del payload es lo que acota el acceso.
export function crearSesionVerificacion(
  verificacionId: string,
  cueAnexo: string,
  ahora: Date = new Date(),
): { valorCookie: string; expiraEn: Date } {
  const expiraEn = new Date(ahora.getTime() + DURACION_SESION_MS)
  const payload = `${verificacionId}|${cueAnexo}|${expiraEn.getTime()}`
  const firma = firmar(payload, obtenerSecreto())
  return { valorCookie: `${payload}.${firma}`, expiraEn }
}

type SesionVerificada = { verificacionId: string; cueAnexo: string; expiraEnMs: number }

// Parseo + verificación de firma + expiración de la COOKIE (no de la
// verificación en la base: eso lo re-chequea el llamador contra la fila real,
// ver acceso-parte.ts). Devuelve null ante cualquier fallo de forma, firma o
// vencimiento — nunca lanza.
function verificarSesion(
  valorCookie: string | undefined | null,
  ahora: Date,
): SesionVerificada | null {
  if (!valorCookie) return null
  const separador = valorCookie.indexOf('.')
  if (separador < 0) return null
  const payload = valorCookie.slice(0, separador)
  const firma = valorCookie.slice(separador + 1)
  if (!payload || !firma) return null

  let secreto: string
  try {
    secreto = obtenerSecreto()
  } catch {
    return null
  }
  const firmaEsperada = firmar(payload, secreto)
  if (!iguales(firma, firmaEsperada)) return null

  const [verificacionId, cueAnexoDelToken, expiraEnMsStr] = payload.split('|')
  if (!verificacionId || !cueAnexoDelToken || !expiraEnMsStr) return null

  const expiraEnMs = Number(expiraEnMsStr)
  if (!Number.isFinite(expiraEnMs) || expiraEnMs <= ahora.getTime()) return null

  return { verificacionId, cueAnexo: cueAnexoDelToken, expiraEnMs }
}

export function sesionVerificacionValidaParaCue(
  valorCookie: string | undefined | null,
  cueAnexo: string,
  ahora: Date = new Date(),
): boolean {
  const sesion = verificarSesion(valorCookie, ahora)
  // El CUE pedido tiene que ser el de esta sesión: el acceso nunca se amplía.
  return sesion !== null && sesion.cueAnexo === cueAnexo
}

// Igual que sesionVerificacionValidaParaCue, pero devuelve el verificacionId
// de la sesión en vez de un booleano cuando la cookie es válida PARA ESE CUE
// (firma correcta, CUE coincide, cookie no vencida). Quien llame TODAVÍA debe
// re-chequear la fila de la verificación en la base (estado, revocación,
// vencimiento del token) antes de conceder acceso — esta función sólo prueba
// que la cookie en sí es auténtica y no vencida, no que la verificación siga
// habilitando escritura.
export function verificacionIdDeSesionValida(
  valorCookie: string | undefined | null,
  cueAnexo: string,
  ahora: Date = new Date(),
): string | null {
  const sesion = verificarSesion(valorCookie, ahora)
  if (!sesion || sesion.cueAnexo !== cueAnexo) return null
  return sesion.verificacionId
}

// Opciones para setear la cookie al canjear el token. secure sólo en
// producción para no romper el desarrollo local sobre HTTP.
export function opcionesCookieSesionVerificacion(expiraEn: Date) {
  return {
    httpOnly: true as const,
    sameSite: 'lax' as const,
    secure: process.env.NODE_ENV === 'production',
    expires: expiraEn,
    path: '/',
  }
}

export function extraerCookieVerificacionSesion(
  cookieHeader: string | null | undefined,
): string | undefined {
  if (!cookieHeader) return undefined
  for (const parte of cookieHeader.split(';')) {
    const igual = parte.indexOf('=')
    if (igual < 0) continue
    const clave = parte.slice(0, igual).trim()
    if (clave === NOMBRE_COOKIE_SESION_VERIFICACION) {
      return decodeURIComponent(parte.slice(igual + 1).trim())
    }
  }
  return undefined
}

// Endpoint público del enlace de verificación escolar (batch E1, protocolo
// ENOS). Valida la credencial de un solo uso SIN consumirla y sin sesión: la
// única credencial es el token que viaja en el body.
//
// Excepción deliberada al criterio "GET sin efectos": esto es una LECTURA
// transportada por POST. El token NUNCA puede ir en la query string de un GET
// porque quedaría registrado en los logs de acceso del servidor (y en
// cualquier proxy intermedio). El cuerpo de un POST no se loguea por defecto.
import { z } from 'zod'
import { ensureSeeded } from '@/lib/db/seed'
import { getClientIp, ipExcedeLimite } from '@/lib/infraestructura/limites'
import { validarCredencial, type VerificacionRow } from '@/lib/infraestructura/verificaciones'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

// Nunca cachear: la respuesta describe una credencial de un solo uso.
// Referrer-Policy evita que un recurso cargado por la página filtre el token
// en un Referer saliente.
const CACHE_HEADERS = {
  'Cache-Control': 'private, no-store',
  'Referrer-Policy': 'no-referrer',
}

// Frases para mostrarle a un director, nunca el motivo técnico.
const MENSAJES: Record<string, string> = {
  credencial_invalida: 'El enlace no es válido.',
  credencial_revocada: 'Este enlace fue revocado.',
  credencial_vencida: 'Este enlace venció.',
  solicitud_cancelada: 'Esta solicitud fue cancelada.',
  no_existe: 'La solicitud no existe.',
}

function mensajeDeMotivo(motivo: string): string {
  return MENSAJES[motivo] ?? 'No se pudo validar el enlace.'
}

// El hash del token jamás sale en una respuesta JSON.
function sinTokenHash(verificacion: VerificacionRow): Omit<VerificacionRow, 'tokenHash'> {
  const { tokenHash: _tokenHash, ...resto } = verificacion
  return resto
}

const bodySchema = z.object({ token: z.string().trim().min(1) })

export async function POST(request: Request, context: { params: Promise<{ id: string }> }) {
  await ensureSeeded()

  const ip = getClientIp(request)
  if (ipExcedeLimite(ip)) {
    return Response.json(
      { error: 'Demasiadas solicitudes. Intente nuevamente más tarde.' },
      { status: 429, headers: CACHE_HEADERS },
    )
  }

  const { id } = await context.params

  let body: unknown
  try {
    body = await request.json()
  } catch {
    return Response.json({ error: 'Cuerpo inválido' }, { status: 400, headers: CACHE_HEADERS })
  }

  const parsed = bodySchema.safeParse(body)
  if (!parsed.success) {
    return Response.json({ error: 'Cuerpo inválido' }, { status: 400, headers: CACHE_HEADERS })
  }

  const resultado = await validarCredencial({ verificacionId: id, token: parsed.data.token })
  if (!resultado.ok) {
    return Response.json(
      { error: mensajeDeMotivo(resultado.motivo) },
      { status: resultado.status, headers: CACHE_HEADERS },
    )
  }

  return Response.json(
    { ok: true, verificacion: sinTokenHash(resultado.verificacion) },
    { status: 200, headers: CACHE_HEADERS },
  )
}

}

// Núcleo compartido por las dos vías de respuesta (enlace público y carga
// asistida por staff). Parametrizado por origen para que la validación de la
// credencial y la atribución de la auditoría vivan en un solo lugar.
//
// Orden deliberado de los chequeos:
//   1. credencial (sólo enlace) ANTES del estado: una credencial inválida
//      nunca debe revelar si la solicitud existe, está cancelada o ya se
//      respondió. Mismo criterio para 403 y para los 410.
//   2. estado persistido, para resolver cancelación y replay idempotente.
//   3. escritura atómica condicionada, con un único reintento si perdió una
//      carrera contra una transición concurrente.
async function transicionarARespondida(
  verificacionId: string,
  resultado: ResultadoRespuesta,
  origen: OrigenRespuesta,
  movimientoId: string | null,
  ahora: Date,
): Promise<ResultadoTransicion> {
  const db = getDb()
  const ahoraIso = ahora.toISOString()
  const canal: CanalRespuesta = origen.tipo === 'enlace' ? 'enlace' : origen.canal

  // Máximo un reintento: si tras re-leer el estado volvemos a perder el
  // UPDATE condicionado, hay una tormenta de transiciones concurrentes que no
  // vale la pena seguir persiguiendo. El diseño congela "una vez más".
  for (let intento = 0; intento < 2; intento += 1) {
    const [fila] = await db
      .select()
      .from(infraVerificacion)
      .where(eq(infraVerificacion.id, verificacionId))
    if (!fila) return { ok: false, status: 404, motivo: 'no_existe' }

    if (origen.tipo === 'enlace') {
      if (hashearToken(origen.token) !== fila.tokenHash) {
        return { ok: false, status: 403, motivo: 'credencial_invalida' }
      }
      if (fila.tokenRevocadoEn !== null) {
        return { ok: false, status: 410, motivo: 'credencial_revocada' }
      }
      if (tokenExpirado(fila.tokenExpiraEn, ahora)) {
        return { ok: false, status: 410, motivo: 'credencial_vencida' }
      }
    }

    if (fila.estado === 'cancelada') {
      return { ok: false, status: 409, motivo: 'solicitud_cancelada' }
    }

    if (fila.estado === 'respondida') {
      // Retry idéntico: idempotente, no escribe un segundo evento. Un retry
      // con otra respuesta es un conflicto real del usuario, no un reintento.
      if (fila.resultado === resultado) return { ok: true, verificacion: fila, replay: true }
      return { ok: false, status: 409, motivo: 'respuesta_contradictoria' }
    }

    // fila.estado === 'pendiente': calcular discrepancia y escribir. La
    // consulta de afectación vigente usa el período del episodio, que es el
    // que ancla el parte del establecimiento.
    const episodio = await obtenerEpisodio(fila.episodioId)
    const hayAfectacion = episodio
      ? await existeAfectacionVigente(fila.cueAnexo, episodio.periodoId)
      : false
    const discrepancia = resultado === 'sin_afectacion' && hayAfectacion ? 1 : 0

    if (resultado === 'con_afectacion' && movimientoId !== null) {
      if (!(await movimientoPerteneceAlCue(movimientoId, fila.cueAnexo))) {
        return { ok: false, status: 409, motivo: 'movimiento_cue_no_coincide' }
      }
    }

    const [actualizada] = await db
      .update(infraVerificacion)
      .set({
        estado: 'respondida',
        resultado,
        respondidaEn: ahoraIso,
        respondidaCanal: canal,
        respondidaPorUserId: origen.tipo === 'asistida' ? origen.actorUserId : null,
        movimientoId,
        discrepancia,
        // La credencial se consume sólo cuando la respuesta vino por enlace.
        // La vía asistida no toca tokenConsumidoEn: el enlace sigue válido si
        // el director todavía no lo usó.
        tokenConsumidoEn: origen.tipo === 'enlace' ? ahoraIso : fila.tokenConsumidoEn,
        actualizadaEn: ahoraIso,
      })
      .where(
        and(
          eq(infraVerificacion.id, verificacionId),
          eq(infraVerificacion.estado, 'pendiente'),
        ),
      )
      .returning()

    if (!actualizada) continue // perdió la carrera: re-lee y reintenta una vez

    await insertarEvento({
      verificacionId,
      tipo: 'respondida',
      origen,
      canal,
      ahoraIso,
    })
    if (discrepancia === 1) {
      await insertarEvento({
        verificacionId,
        tipo: 'discrepancia_detectada',
        origen,
        canal,
        ahoraIso,
      })
    }
    return { ok: true, verificacion: actualizada }
  }

  // Se perdió la carrera dos veces seguidas: el estado siguió cambiando bajo
  // los pies. No es un camino alcanzable en operación normal; se informa como
  // conflicto en vez de inventar un resultado.
  return { ok: false, status: 409, motivo: 'conflicto_concurrente' }
}

export async function responderPorEnlace(
  input: ResponderPorEnlaceInput,
  ahora: Date = new Date(),
): Promise<ResultadoTransicion> {
  // Error de programación del caller, no un caso de usuario: una respuesta
  // 'con_afectacion' sin movimiento es un dato incompleto que no debe
  // persistirse.
  if (input.resultado === 'con_afectacion' && !input.movimientoId) {
    throw new Error('con_afectacion requiere movimientoId')
  }
  return transicionarARespondida(
    input.verificacionId,
    input.resultado,
    { tipo: 'enlace', token: input.token },
    input.movimientoId ?? null,
    ahora,
  )
}

export async function responderAsistida(
  input: ResponderAsistidaInput,
  ahora: Date = new Date(),
): Promise<ResultadoTransicion> {
  if (input.resultado === 'con_afectacion' && !input.movimientoId) {
    throw new Error('con_afectacion requiere movimientoId')
  }
  return transicionarARespondida(
    input.verificacionId,
    input.resultado,
    { tipo: 'asistida', actorUserId: input.actorUserId, canal: input.canal },
    input.movimientoId ?? null,
    ahora,
  )
}

// Chequeo de SÓLO LECTURA para que la página pública muestre el estado antes
// de que el director elija una respuesta. No escribe, no consume el token y no
// valida contra un resultado (todavía no hay uno). Misma secuencia de
// validación de credencial que transicionarARespondida, sin el paso de
// escritura. Si ya está respondida se devuelve igual como ok: la página
// necesita poder mostrar el resultado final, no ocultarlo.
export async function validarCredencial(
  input: { verificacionId: string; token: string },
  ahora: Date = new Date(),
): Promise<
  | { ok: true; verificacion: VerificacionRow }
  | { ok: false; status: 403 | 404 | 409 | 410; motivo: string }
> {
  const db = getDb()
  const [fila] = await db
    .select()
    .from(infraVerificacion)
    .where(eq(infraVerificacion.id, input.verificacionId))
  if (!fila) return { ok: false, status: 404, motivo: 'no_existe' }

  if (hashearToken(input.token) !== fila.tokenHash) {
    return { ok: false, status: 403, motivo: 'credencial_invalida' }
  }
  if (fila.tokenRevocadoEn !== null) {
    return { ok: false, status: 410, motivo: 'credencial_revocada' }
  }
  if (tokenExpirado(fila.tokenExpiraEn, ahora)) {
    return { ok: false, status: 410, motivo: 'credencial_vencida' }
  }
  if (fila.estado === 'cancelada') {
    return { ok: false, status: 409, motivo: 'solicitud_cancelada' }
  }
  return { ok: true, verificacion: fila }
}

// Regla de N1 (gate del batch E1): la sesión derivada del token nunca puede
// ser más fuerte que el token. Esta función es el único lugar que decide si
// una verificación sigue habilitando ESCRITURA: se usa tanto al canjear una
// sesión nueva (canjear-sesion) como en CADA request que reusa una sesión ya
// emitida (tieneAccesoAlParteParaCue en acceso-parte.ts) — nunca basta con
// que la cookie tenga firma/expiración válidas, la fila real de la
// verificación manda siempre.
export async function verificacionHabilitaSesionEscritura(
  verificacionId: string,
  ahora: Date = new Date(),
): Promise<boolean> {
  const fila = await obtenerVerificacion(verificacionId)
  if (!fila) return false
  if (fila.estado !== 'pendiente') return false
  if (fila.tokenRevocadoEn !== null) return false
  if (tokenExpirado(fila.tokenExpiraEn, ahora)) return false
  return true
}

export async function obtenerVerificacion(
  verificacionId: string,
): Promise<VerificacionRow | null> {
  const db = getDb()
  const [fila] = await db
    .select()
    .from(infraVerificacion)
    .where(eq(infraVerificacion.id, verificacionId))
  return fila ?? null
}

export async function listarVerificaciones(
  input?: { episodioId?: string; cueAnexo?: string; estado?: 'pendiente' | 'respondida' | 'cancelada' },
): Promise<VerificacionRow[]> {
  const db = getDb()
  const condiciones = []
  if (input?.episodioId) condiciones.push(eq(infraVerificacion.episodioId, input.episodioId))
  if (input?.cueAnexo) condiciones.push(eq(infraVerificacion.cueAnexo, input.cueAnexo))
  if (input?.estado) condiciones.push(eq(infraVerificacion.estado, input.estado))

  const base = db.select().from(infraVerificacion)
  const conFiltro = condiciones.length > 0 ? base.where(and(...condiciones)) : base
  return conFiltro.orderBy(desc(infraVerificacion.solicitadaEn))
}

// Auditoría de un intento de vínculo fallido (batch E1): quien llama a esto ya
// tiene un movimiento real guardado (el parte del director se guardó bien) y
// el vínculo con la verificación de origen no prendió por el motivo que sea
// (credencial inválida/vencida/revocada, respuesta contradictoria, etc.). Esto
// NO reintenta la transición ni toca `estado`/`resultado`/`movimientoId` de la
// verificación: sólo dejar un rastro append-only para que el operador vea que
// hubo un intento de responder con afectación que no quedó enlazado. Si el id
// de verificación ni siquiera existe (token completamente ajeno/inventado), no
// hay nada real que auditar: no se escribe nada y se devuelve false.
export async function registrarIntentoVinculoFallido(
  input: { verificacionId: string; motivo: string },
  ahora: Date = new Date(),
): Promise<boolean> {
  const db = getDb()
  const [fila] = await db
    .select({ id: infraVerificacion.id })
    .from(infraVerificacion)
    .where(eq(infraVerificacion.id, input.verificacionId))
  if (!fila) return false

  await db.insert(infraVerificacionEvento).values({
    id: randomUUID(),
    verificacionId: input.verificacionId,
    tipo: 'vinculo_fallido',
    actorTipo: 'sistema',
    actorUserId: null,
    canal: null,
    motivo: input.motivo,
    correlacionId: null,
    creadaEn: ahora.toISOString(),
  })
  return true
}

// Endpoint público del enlace de verificación escolar (batch E1, protocolo
// ENOS). Canjea la credencial de un solo uso por una sesión acotada por CUE:
// sin consumir el token (es sólo lectura, igual que validar-token), setea la
// cookie `verificacion_sesion` que habilita el formulario de parte
// (POST /api/problematicas/parte) SIN la contraseña compartida, y únicamente
// para el CUE exacto de esta verificación.
//
// Misma excepción deliberada que validar-token: es una LECTURA transportada
// por POST. El token nunca puede ir en la query string de un GET porque
// quedaría registrado en los logs de acceso del servidor.
import { NextResponse } from 'next/server'
import { z } from 'zod'
import { ensureSeeded } from '@/lib/db/seed'
import { getClientIp, ipExcedeLimite } from '@/lib/infraestructura/limites'
import {
  NOMBRE_COOKIE_SESION_VERIFICACION,
  crearSesionVerificacion,
  opcionesCookieSesionVerificacion,
} from '@/lib/infraestructura/verificacion-sesion'
import {
  validarCredencial,
  verificacionHabilitaSesionEscritura,
  type VerificacionRow,
} from '@/lib/infraestructura/verificaciones'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

// Nunca cachear: la respuesta describe una credencial de un solo uso.
// Referrer-Policy evita que un recurso cargado por la página filtre el token
// en un Referer saliente.
const CACHE_HEADERS = {
  'Cache-Control': 'private, no-store',
  'Referrer-Policy': 'no-referrer',
}

// Frases para mostrarle a un director, nunca el motivo técnico.
const MENSAJES: Record<string, string> = {
  credencial_invalida: 'El enlace no es válido.',
  credencial_revocada: 'Este enlace fue revocado.',
  credencial_vencida: 'Este enlace venció.',
  solicitud_cancelada: 'Esta solicitud fue cancelada.',
  no_existe: 'La solicitud no existe.',
}

function mensajeDeMotivo(motivo: string): string {
  return MENSAJES[motivo] ?? 'No se pudo validar el enlace.'
}

// El hash del token jamás sale en una respuesta JSON.
function sinTokenHash(verificacion: VerificacionRow): Omit<VerificacionRow, 'tokenHash'> {
  const { tokenHash: _tokenHash, ...resto } = verificacion
  return resto
}

const bodySchema = z.object({ token: z.string().trim().min(1) })

export async function POST(request: Request, context: { params: Promise<{ id: string }> }) {
  await ensureSeeded()

  const ip = getClientIp(request)
  if (ipExcedeLimite(ip)) {
    return Response.json(
      { error: 'Demasiadas solicitudes. Intente nuevamente más tarde.' },
      { status: 429, headers: CACHE_HEADERS },
    )
  }

  const { id } = await context.params

  let body: unknown
  try {
    body = await request.json()
  } catch {
    return Response.json({ error: 'Cuerpo inválido' }, { status: 400, headers: CACHE_HEADERS })
  }

  const parsed = bodySchema.safeParse(body)
  if (!parsed.success) {
    return Response.json({ error: 'Cuerpo inválido' }, { status: 400, headers: CACHE_HEADERS })
  }

  const resultado = await validarCredencial({ verificacionId: id, token: parsed.data.token })
  if (!resultado.ok) {
    return Response.json(
      { error: mensajeDeMotivo(resultado.motivo) },
      { status: resultado.status, headers: CACHE_HEADERS },
    )
  }

  // Regla de N1: la credencial puede seguir siendo válida (validarCredencial
  // es de sólo lectura, para mostrar el comprobante) pero una verificación ya
  // respondida/cancelada o con el token revocado/vencido NO puede canjear una
  // sesión nueva. 409 y no 403/410: la credencial en sí está bien; lo que
  // cambió es el estado de la solicitud (esos otros casos ya los cubre
  // validarCredencial antes de llegar acá).
  if (!(await verificacionHabilitaSesionEscritura(id))) {
    return Response.json(
      { error: 'Esta solicitud ya fue respondida.' },
      { status: 409, headers: CACHE_HEADERS },
    )
  }

  // La sesión se acota al CUE de la verificación canjeada: nunca a otro.
  const { valorCookie, expiraEn } = crearSesionVerificacion(id, resultado.verificacion.cueAnexo)
  const respuesta = NextResponse.json(
    { ok: true, verificacion: sinTokenHash(resultado.verificacion) },
    { status: 200, headers: CACHE_HEADERS },
  )
  respuesta.cookies.set(
    NOMBRE_COOKIE_SESION_VERIFICACION,
    valorCookie,
    opcionesCookieSesionVerificacion(expiraEn),
  )
  return respuesta
}

import type { Metadata } from 'next'
import { VerificacionResponder } from '@/components/infraestructura/verificacion-responder'
import { resolverContextoPorCue } from '@/lib/infraestructura/contexto'
import { ensureGeSchema, openGeDb } from '@/lib/infraestructura/ge-db'
import { obtenerVerificacion } from '@/lib/infraestructura/verificaciones'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

export const metadata: Metadata = {
  title: 'Verificación escolar',
}

/**
 * Puerta de entrada del enlace de verificación escolar del batch E1
 * (protocolo ENOS). Pública a propósito y SIN guarda de acceso: la única
 * credencial es el token que viaja en la query string del enlace y que se
 * reenvía por POST en el cuerpo — nunca se lee ni se registra acá.
 *
 * La página no llama a ninguna API: toda la lógica de red vive en el
 * componente cliente, que valida el token al montar. Sólo resuelve el nombre
 * del establecimiento del lado del servidor (lectura local de GE), como
 * adorno: si no está disponible, la pantalla sigue funcionando con el CUE.
 */
export default async function VerificacionPage({
  params,
  searchParams,
}: {
  params: Promise<{ id: string }>
  searchParams: Promise<{ token?: string }>
}) {
  const { id } = await params
  const { token } = await searchParams

  if (!token) {
    return (
      <div className="publico-content">
        <div className="estado-actual-aviso">
          <p className="estado-actual-aviso__texto" role="alert">
            Este enlace no incluye la credencial de acceso.
          </p>
        </div>
      </div>
    )
  }

  // El nombre de la escuela es un adorno: nunca debe romper la página. Se
  // resuelve SÓLO para el CUE de esta verificación (el id del path no es
  // secreto; el token sigue siendo la única credencial).
  const fila = await obtenerVerificacion(id).catch(() => null)
  let escuelaNombre: string | undefined
  if (fila) {
    const client = openGeDb()
    try {
      await ensureGeSchema(client)
      const resultado = await resolverContextoPorCue(client, fila.cueAnexo)
      if (resultado.ok) escuelaNombre = resultado.contexto.escuela.nombre
    } catch {
      // GE no disponible: se sigue con el CUE.
    } finally {
      client.close()
    }
  }

  return (
    <div className="publico-content">
      <VerificacionResponder
        verificacionId={id}
        token={token}
        escuelaNombre={escuelaNombre}
      />
    </div>
  )
}

'use client'

import { useEffect, useState } from 'react'
import { useRouter } from 'next/navigation'
import { Button } from '@/components/ui/button'
import { formatearCargaCorta } from './historial-formato'

// Forma pública de una verificación del batch E1 tal como la devuelven los
// endpoints del enlace. `tokenHash` nunca llega al navegador: el Route Handler
// lo quita antes de responder.
export interface VerificacionEnlace {
  cueAnexo: string
  estado: 'pendiente' | 'respondida' | 'cancelada'
  resultado: 'sin_afectacion' | 'con_afectacion' | 'no_disponible' | null
  respondidaEn: string | null
  discrepancia: number | boolean
}

interface VerificacionResponderProps {
  verificacionId: string
  token: string
  escuelaNombre?: string
}

type AccionRespuesta = 'sin_afectacion'

// Máquina de estados de la pantalla. Un discriminante único: cada render sabe
// exactamente qué mostrar y qué acciones existen, sin banderas sueltas.
type Maquina =
  | { estado: 'cargando' }
  | { estado: 'error'; mensaje: string }
  | { estado: 'pendiente'; verificacion: VerificacionEnlace; mensaje?: string }
  | { estado: 'confirmar'; verificacion: VerificacionEnlace; accion: AccionRespuesta }
  | {
      estado: 'enviando'
      verificacion: VerificacionEnlace
      accion: AccionRespuesta | 'canjear_sesion'
    }
  | { estado: 'comprobante'; verificacion: VerificacionEnlace }
  | { estado: 'ir_a_parte' }

// La lee la pieza que completa el enlace del movimiento (otra tarea del batch);
// acá sólo se guarda antes de navegar al formulario de parte.
const CLAVE_VINCULO = 'e1-verificacion-vinculo'

const PREGUNTA =
  '¿Su escuela tiene actualmente alguna afectación por la situación hidrometeorológica?'
const CONFIRMACION_SIN_AFECTACION =
  '¿Confirma que la escuela NO tiene afectación en este momento?'
const TEXTO_ERROR_SIN_SALIDA =
  'Si cree que esto es un error, comuníquese con quien le compartió el enlace.'
const NOTA_DISCREPANCIA =
  "Se registró como 'sin afectación', pero el sistema tenía una afectación vigente para esta escuela. Un operador va a revisar esta diferencia."

function nombreEscuela(escuelaNombre: string | undefined, cueAnexo: string): string {
  return escuelaNombre ? `${escuelaNombre} (CUE ${cueAnexo})` : `Escuela ${cueAnexo}`
}

function textoResultado(verificacion: VerificacionEnlace): string {
  if (verificacion.estado === 'cancelada') return 'Cancelada'
  switch (verificacion.resultado) {
    case 'sin_afectacion':
      return 'Sin afectación'
    case 'con_afectacion':
      return 'Con afectación'
    case 'no_disponible':
      return 'No disponible'
    default:
      return 'Sin respuesta'
  }
}

// El mensaje de la API ya viene en español para el director; sólo se cae al
// texto por defecto si el cuerpo no trae uno legible.
async function leerError(respuesta: Response, porDefecto: string): Promise<string> {
  const cuerpo = await respuesta.json().catch(() => null)
  return cuerpo?.error ?? porDefecto
}

export function VerificacionResponder({
  verificacionId,
  token,
  escuelaNombre,
}: VerificacionResponderProps) {
  const router = useRouter()
  const [maquina, setMaquina] = useState<Maquina>({ estado: 'cargando' })

  useEffect(() => {
    let activo = true

    async function validar() {
      try {
        const respuesta = await fetch(
          `/api/problematicas/verificaciones/${verificacionId}/validar-token`,
          {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ token }),
          },
        )
        if (!activo) return
        if (typeof window !== 'undefined') {
          window.history.replaceState(null, '', window.location.pathname)
        }
        if (!respuesta.ok) {
          setMaquina({
            estado: 'error',
            mensaje: await leerError(respuesta, 'No se pudo validar el enlace.'),
          })
          return
        }
        const cuerpo = await respuesta.json()
        if (!activo) return
        const verificacion = cuerpo?.verificacion as VerificacionEnlace
        if (verificacion?.estado === 'pendiente') {
          setMaquina({ estado: 'pendiente', verificacion })
        } else {
          // Ya respondida o cancelada: no hay nada que hacer, se muestra el
          // comprobante/estado final directamente.
          setMaquina({ estado: 'comprobante', verificacion })
        }
      } catch {
        if (activo) {
          if (typeof window !== 'undefined') {
            window.history.replaceState(null, '', window.location.pathname)
          }
          setMaquina({ estado: 'error', mensaje: 'No se pudo validar el enlace.' })
        }
      }
    }

    validar()
    return () => {
      activo = false
    }
  }, [verificacionId, token])

  async function responderSinAfectacion(verificacion: VerificacionEnlace) {
    setMaquina({ estado: 'enviando', verificacion, accion: 'sin_afectacion' })
    try {
      const respuesta = await fetch(
        `/api/problematicas/verificaciones/${verificacionId}/responder`,
        {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ token, resultado: 'sin_afectacion' }),
        },
      )
      if (!respuesta.ok) {
        const mensaje = await leerError(respuesta, 'No se pudo registrar la respuesta.')
        // Credencial dura (revocada/vencida/inexistente): no tiene sentido
        // volver a preguntar. El resto (por ejemplo un 409) sí vuelve a la
        // pantalla principal con el mensaje a la vista.
        if ([403, 404, 410].includes(respuesta.status)) {
          setMaquina({ estado: 'error', mensaje })
        } else {
          setMaquina({ estado: 'pendiente', verificacion, mensaje })
        }
        return
      }
      const cuerpo = await respuesta.json()
      setMaquina({ estado: 'comprobante', verificacion: cuerpo.verificacion })
    } catch {
      setMaquina({
        estado: 'pendiente',
        verificacion,
        mensaje: 'No se pudo registrar la respuesta.',
      })
    }
  }

  async function irAlParte(verificacion: VerificacionEnlace) {
    setMaquina({ estado: 'enviando', verificacion, accion: 'canjear_sesion' })
    try {
      const respuesta = await fetch(
        `/api/problematicas/verificaciones/${verificacionId}/canjear-sesion`,
        {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ token }),
        },
      )
      if (!respuesta.ok) {
        setMaquina({
          estado: 'error',
          mensaje: await leerError(respuesta, 'No se pudo validar el enlace.'),
        })
        return
      }
      // El enlace automático del movimiento (otra tarea) lee esta clave. Se
      // guarda ANTES de navegar para que esté disponible al montar el parte.
      sessionStorage.setItem(CLAVE_VINCULO, JSON.stringify({ id: verificacionId, token }))
      setMaquina({ estado: 'ir_a_parte' })
      // La cookie de sesión ya quedó seteada por el fetch anterior; el push de
      // Next la aprovecha en la misma navegación SPA.
      router.push(`/problematicas/parte?cue=${encodeURIComponent(verificacion.cueAnexo)}`)
    } catch {
      setMaquina({ estado: 'error', mensaje: 'No se pudo validar el enlace.' })
    }
  }

  if (maquina.estado === 'cargando') {
    return (
      <div className="verificacion-pantalla">
        <p className="estado-actual-aviso__texto" role="status">
          Verificando el enlace…
        </p>
      </div>
    )
  }

  if (maquina.estado === 'enviando') {
    return (
      <div className="verificacion-pantalla">
        <p className="estado-actual-aviso__texto" role="status">
          {maquina.accion === 'canjear_sesion'
            ? 'Abriendo el formulario…'
            : 'Registrando la respuesta…'}
        </p>
      </div>
    )
  }

  if (maquina.estado === 'ir_a_parte') {
    return (
      <div className="verificacion-pantalla">
        <p className="estado-actual-aviso__texto" role="status">
          Abriendo el formulario…
        </p>
      </div>
    )
  }

  if (maquina.estado === 'error') {
    return (
      <div className="verificacion-pantalla">
        <div className="estado-actual-aviso">
          <p className="estado-actual-aviso__texto" role="alert">
            {maquina.mensaje}
          </p>
          <p className="estado-actual-aviso__texto">{TEXTO_ERROR_SIN_SALIDA}</p>
        </div>
      </div>
    )
  }

  if (maquina.estado === 'pendiente') {
    return (
      <div className="verificacion-pantalla">
        <h1 className="publico-content__title">
          {nombreEscuela(escuelaNombre, maquina.verificacion.cueAnexo)}
        </h1>

        {maquina.mensaje && (
          <div className="estado-actual-aviso">
            <p className="estado-actual-aviso__texto" role="alert">
              {maquina.mensaje}
            </p>
          </div>
        )}

        <p className="verificacion-pregunta">{PREGUNTA}</p>

        <div className="verificacion-acciones">
          <Button
            className="verificacion-boton"
            onClick={() =>
              setMaquina({
                estado: 'confirmar',
                verificacion: maquina.verificacion,
                accion: 'sin_afectacion',
              })
            }
          >
            Sin afectación
          </Button>
          <Button
            className="verificacion-boton"
            onClick={() => irAlParte(maquina.verificacion)}
          >
            Hay afectación
          </Button>
        </div>
      </div>
    )
  }

  if (maquina.estado === 'confirmar') {
    return (
      <div className="verificacion-pantalla">
        <p className="verificacion-pregunta">{CONFIRMACION_SIN_AFECTACION}</p>

        <div className="verificacion-acciones">
          <Button
            className="verificacion-boton"
            onClick={() => responderSinAfectacion(maquina.verificacion)}
          >
            Confirmar
          </Button>
          <Button
            className="verificacion-boton"
            variant="secondary"
            onClick={() =>
              setMaquina({ estado: 'pendiente', verificacion: maquina.verificacion })
            }
          >
            Volver
          </Button>
        </div>
      </div>
    )
  }

  const { verificacion } = maquina
  const fecha = verificacion.respondidaEn
    ? formatearCargaCorta(verificacion.respondidaEn)
    : ''

  return (
    <div className="verificacion-pantalla">
      <section className="estado-actual-bloque verificacion-comprobante">
        <h2 className="estado-actual-bloque__titulo">Respuesta registrada</h2>
        <p className="estado-actual-bloque__valor">{textoResultado(verificacion)}</p>
        <p className="estado-actual-bloque__vigencia">
          {nombreEscuela(escuelaNombre, verificacion.cueAnexo)}
        </p>

        {verificacion.estado === 'cancelada' && (
          <p className="estado-actual-bloque__vacio">Esta solicitud fue cancelada.</p>
        )}

        {fecha && (
          <p className="estado-actual-bloque__vigencia">Respondida el {fecha}</p>
        )}

        {verificacion.discrepancia && (
          <p className="estado-actual-bloque__vacio">{NOTA_DISCREPANCIA}</p>
        )}
      </section>
    </div>
  )
}

// @vitest-environment jsdom
import { render, screen, fireEvent, waitFor, cleanup } from '@testing-library/react'
import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest'
import { VerificacionResponder, type VerificacionEnlace } from './verificacion-responder'

const { pushMock } = vi.hoisted(() => ({ pushMock: vi.fn() }))

vi.mock('next/navigation', () => ({
  useRouter: () => ({ push: pushMock, refresh: vi.fn() }),
}))

function jsonResponse(body: unknown, status = 200) {
  return { ok: status >= 200 && status < 300, status, json: async () => body } as Response
}

const VERIFICACION_PENDIENTE: VerificacionEnlace = {
  cueAnexo: '1801605-04',
  estado: 'pendiente',
  resultado: null,
  respondidaEn: null,
  discrepancia: 0,
}

const PROPS = { verificacionId: 'verif-1', token: 'token-secreto' }

function renderResponder() {
  return render(<VerificacionResponder {...PROPS} />)
}

/** Mock de fetch que despacha por sufijo del endpoint y permite overrides. */
function stubFetch(
  overrides: {
    validar?: Response
    responder?: Response
    canjear?: Response
  } = {},
) {
  const fetchMock = vi.fn(async (url: string, _init?: RequestInit) => {
    const ruta = String(url)
    if (ruta.endsWith('/validar-token')) {
      return overrides.validar ?? jsonResponse({ ok: true, verificacion: VERIFICACION_PENDIENTE })
    }
    if (ruta.endsWith('/responder')) {
      return (
        overrides.responder ??
        jsonResponse({
          ok: true,
          verificacion: {
            ...VERIFICACION_PENDIENTE,
            estado: 'respondida',
            resultado: 'sin_afectacion',
            respondidaEn: '2026-09-18T13:35:00.000Z',
          },
        })
      )
    }
    if (ruta.endsWith('/canjear-sesion')) {
      return overrides.canjear ?? jsonResponse({ ok: true, verificacion: VERIFICACION_PENDIENTE })
    }
    throw new Error(`fetch inesperado: ${ruta}`)
  })
  vi.stubGlobal('fetch', fetchMock)
  return fetchMock
}

beforeEach(() => {
  pushMock.mockReset()
})

afterEach(() => {
  cleanup()
  sessionStorage.clear()
  vi.unstubAllGlobals()
  document.body.innerHTML = ''
})

describe('VerificacionResponder — carga inicial', () => {
  it('valida el token al montar y muestra la pregunta con las dos acciones', async () => {
    const fetchMock = stubFetch()
    renderResponder()

    expect(
      await screen.findByText(
        '¿Su escuela tiene actualmente alguna afectación por la situación hidrometeorológica?',
      ),
    ).toBeInTheDocument()
    expect(screen.getByText('Escuela 1801605-04')).toBeInTheDocument()
    expect(screen.getByRole('button', { name: 'Sin afectación' })).toBeInTheDocument()
    expect(screen.getByRole('button', { name: 'Hay afectación' })).toBeInTheDocument()

    const [url, init] = fetchMock.mock.calls[0]
    expect(String(url)).toBe('/api/problematicas/verificaciones/verif-1/validar-token')
    expect(init?.method).toBe('POST')
    expect(JSON.parse(String(init?.body))).toEqual({ token: PROPS.token })
  })

  it('muestra el error de la API sin opciones de acción cuando el token es inválido', async () => {
    stubFetch({ validar: jsonResponse({ error: 'Este enlace venció.' }, 410) })
    renderResponder()

    expect(await screen.findByRole('alert')).toHaveTextContent('Este enlace venció.')
    expect(
      screen.getByText(/comuníquese con quien le compartió el enlace/i),
    ).toBeInTheDocument()
    expect(screen.queryByRole('button', { name: 'Sin afectación' })).toBeNull()
    expect(screen.queryByRole('button', { name: 'Hay afectación' })).toBeNull()
  })
})

describe('VerificacionResponder — sin afectación', () => {
  it('pide confirmación, envía la respuesta y muestra el comprobante', async () => {
    const fetchMock = stubFetch()
    renderResponder()

    fireEvent.click(await screen.findByRole('button', { name: 'Sin afectación' }))

    expect(
      screen.getByText('¿Confirma que la escuela NO tiene afectación en este momento?'),
    ).toBeInTheDocument()

    fireEvent.click(screen.getByRole('button', { name: 'Confirmar' }))

    expect(await screen.findByText('Sin afectación')).toBeInTheDocument()

    const llamada = fetchMock.mock.calls.find(([url]) => String(url).endsWith('/responder'))
    expect(llamada).toBeDefined()
    expect(JSON.parse(String(llamada?.[1]?.body))).toEqual({
      token: PROPS.token,
      resultado: 'sin_afectacion',
    })
  })

  it('"Volver" regresa a la pregunta sin enviar nada', async () => {
    const fetchMock = stubFetch()
    renderResponder()

    fireEvent.click(await screen.findByRole('button', { name: 'Sin afectación' }))
    fireEvent.click(screen.getByRole('button', { name: 'Volver' }))

    expect(
      screen.getByText(
        '¿Su escuela tiene actualmente alguna afectación por la situación hidrometeorológica?',
      ),
    ).toBeInTheDocument()
    expect(fetchMock.mock.calls.some(([url]) => String(url).endsWith('/responder'))).toBe(false)
  })
})

describe('VerificacionResponder — hay afectación', () => {
  it('canjea la sesión, guarda el vínculo y navega al parte con el CUE', async () => {
    const fetchMock = stubFetch()
    renderResponder()

    fireEvent.click(await screen.findByRole('button', { name: 'Hay afectación' }))

    await waitFor(() => {
      expect(pushMock).toHaveBeenCalledWith('/problematicas/parte?cue=1801605-04')
    })

    expect(JSON.parse(String(sessionStorage.getItem('e1-verificacion-vinculo')))).toEqual({
      id: PROPS.verificacionId,
      token: PROPS.token,
    })

    const llamada = fetchMock.mock.calls.find(([url]) =>
      String(url).endsWith('/canjear-sesion'),
    )
